import sys
from decimal import Decimal, ROUND_HALF_UP


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        a_str, op, b_str = parts
        a = Decimal(a_str)
        b = Decimal(b_str)
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "/":
            if b == 0:
                print("ERROR")
                continue
            result = (a / b).quantize(Decimal("1.0000000000"), rounding=ROUND_HALF_UP)
        else:
            continue
        # Format the result as per specification
        if result == int(result):
            print(str(int(result)))
        elif result < 0:
            print(f"{result}")
        else:
            s = f"{result}".rstrip('0').rstrip('.')
            if '.' in s:
                print(s)
            else:
                print("0")


if __name__ == "__main__":
    main()
